-- BACKLOG-3998 DB harness: C14 rollback then re-apply. Generated by compose.py; see README.md.
-- Synthetic accounts '<tag>-3998-...@example.test' (test naming only).
-- BACKLOG-3998 rollback: removes the three triggers and the four functions this
-- migration adds, drops the update policy's WITH CHECK, and re-creates handle_new_user
-- and admin_add_internal_user with the bodies measured on production and keepr-test
-- before the migration (md5(prosrc) 64c98e28c6916d1095fd70445e7812cf and
-- 058aebe462132d39c60ab4cfdf9dbd55, checked at the end). public.users.email values the
-- migration's data step rewrote are NOT restored.
-- Run as one statement batch; then delete the ledger row if it was applied through it:
--   DELETE FROM supabase_migrations.schema_migrations WHERE version = '20261016070000';

DROP TRIGGER IF EXISTS users_email_from_auth ON public.users;
DROP TRIGGER IF EXISTS users_client_write_guard ON public.users;
DROP TRIGGER IF EXISTS on_auth_user_email_changed ON auth.users;
DROP FUNCTION IF EXISTS public.users_email_from_auth();
DROP FUNCTION IF EXISTS public.users_client_write_guard();
DROP FUNCTION IF EXISTS public.users_own_oauth_pair();
DROP FUNCTION IF EXISTS public.user_id_for_auth_email(text);
DROP FUNCTION IF EXISTS public.sync_email_from_auth();

DROP POLICY IF EXISTS users_can_update_own_user ON public.users;
CREATE POLICY users_can_update_own_user ON public.users
  FOR UPDATE USING ((SELECT auth.uid()) = id);

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_email TEXT;
  v_existing_id UUID;
BEGIN
  -- Handle null or empty email - use fallback
  v_email := COALESCE(
    NULLIF(TRIM(NEW.email), ''),
    NULLIF(TRIM(NEW.raw_user_meta_data->>'email'), ''),
    NEW.id::text || '@unknown.local'
  );

  -- Check if a user with this email already exists (orphaned from previous auth)
  SELECT id INTO v_existing_id FROM public.users WHERE email = v_email;

  IF v_existing_id IS NOT NULL AND v_existing_id != NEW.id THEN
    -- Email exists with different ID - delete orphaned record and its related data
    -- This handles the case where user was deleted from auth but not public.users
    
    -- Delete related analytics_events first (FK constraint)
    DELETE FROM public.analytics_events WHERE user_id = v_existing_id;
    
    -- Delete the orphaned user record
    DELETE FROM public.users WHERE id = v_existing_id;
  END IF;

  -- Now insert the new user (or update if somehow exists with same ID)
  INSERT INTO public.users (
    id, email, display_name, avatar_url, oauth_provider, oauth_id,
    created_at, updated_at, is_active, status
  )
  VALUES (
    NEW.id,
    v_email,
    COALESCE(NEW.raw_user_meta_data->>'full_name', NEW.raw_user_meta_data->>'name', split_part(v_email, '@', 1)),
    NEW.raw_user_meta_data->>'avatar_url',
    COALESCE(NEW.raw_app_meta_data->>'provider', 'email'),
    COALESCE(NEW.raw_user_meta_data->>'provider_id', NEW.raw_user_meta_data->>'sub', NEW.id::text),
    NOW(),
    NOW(),
    true,
    'active'
  )
  ON CONFLICT (id) DO UPDATE SET
    email = EXCLUDED.email,
    display_name = COALESCE(EXCLUDED.display_name, public.users.display_name),
    avatar_url = COALESCE(EXCLUDED.avatar_url, public.users.avatar_url),
    updated_at = NOW();

  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.admin_add_internal_user(p_email text, p_role text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_target_user_id UUID;
  v_role_id UUID;
  v_existing RECORD;
BEGIN
  IF NOT public.has_internal_role(auth.uid()) THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  SELECT id INTO v_role_id FROM public.admin_roles WHERE slug = REPLACE(p_role, '_', '-');
  IF v_role_id IS NULL THEN
    RAISE EXCEPTION 'Invalid role: %', p_role;
  END IF;

  SELECT id INTO v_target_user_id FROM public.users WHERE email = p_email;
  IF v_target_user_id IS NULL THEN
    RAISE EXCEPTION 'No user found with email: %', p_email;
  END IF;

  SELECT * INTO v_existing FROM public.internal_roles WHERE user_id = v_target_user_id;
  IF FOUND THEN
    RAISE EXCEPTION 'User already has an internal role';
  END IF;

  INSERT INTO public.internal_roles (user_id, role_id, created_by)
  VALUES (v_target_user_id, v_role_id, auth.uid());

  PERFORM public.log_admin_action(
    'internal_user.add',
    'internal_role',
    v_target_user_id::TEXT,
    jsonb_build_object(
      'after', jsonb_build_object(
        'email', p_email,
        'role', p_role,
        'user_id', v_target_user_id
      )
    )
  );

  RETURN jsonb_build_object('success', true, 'user_id', v_target_user_id, 'role', p_role);
END;
$function$;

DO $chk$
DECLARE v text;
BEGIN
  SELECT string_agg(p.proname || '=' || md5(p.prosrc), ' ' ORDER BY p.proname) INTO v FROM pg_proc p
   WHERE p.pronamespace = 'public'::regnamespace AND p.proname IN ('handle_new_user', 'admin_add_internal_user');
  IF v IS DISTINCT FROM 'admin_add_internal_user=058aebe462132d39c60ab4cfdf9dbd55 handle_new_user=64c98e28c6916d1095fd70445e7812cf' THEN
    RAISE EXCEPTION '3998 rollback: restored bodies do not match the pinned md5s: %', v;
  END IF;
END $chk$;

-- BACKLOG-3998: public.users.email is set from auth.users; address lookups match
-- auth.users; a client statement on its own public.users row cannot set the sign-in
-- identity pair or the provisioning / licence / subscription columns.
--
-- 1. public.users_email_from_auth() (trigger users_email_from_auth, BEFORE INSERT OR
--    UPDATE OF email, id ON public.users). SECURITY DEFINER, same rule for every role.
--    The row has an auth.users record -> email := lower(btrim(auth email)); an empty
--    auth email gives '<id>@unknown.local'. If another public.users row already holds
--    that value, the row gets '<id>@unknown.local' instead (never an error, so it can
--    never fail a sign-in). No auth.users record (rows written by SCIM or directory sync
--    before the person's first sign-in) -> the email that was written is kept.
-- 2. users_can_update_own_user gets WITH CHECK (auth.uid() = id): an update keeps the
--    row on the caller's own id.
-- 3. public.users_client_write_guard() (trigger users_client_write_guard, BEFORE INSERT
--    OR UPDATE OF oauth_provider, oauth_id ON public.users). SECURITY INVOKER; acts only
--    on statements run directly by the authenticated / anon roles (the same test as
--    guard_organization_client_update). Server writers (service_role, SECURITY DEFINER
--    functions, handle_new_user) are unchanged.
--    - UPDATE: oauth_provider and oauth_id keep their stored values.
--    - INSERT: oauth_provider / oauth_id come from public.users_own_oauth_pair()
--      (auth.identities); and every column below takes its column default, whatever
--      the statement sent: status, suspended_at, suspension_reason, is_active,
--      subscription_tier, subscription_status, subscription_started_at, trial_ends_at,
--      provisioning_source, scim_external_id, is_managed, sso_only, last_sso_login_at,
--      last_sso_provider, jit_provisioned, jit_provisioned_at, idp_claims.
--    No error is raised: an installed desktop that sends these values keeps working.
-- 4. public.users_own_oauth_pair(): the caller's (provider, provider_id) from
--    auth.identities (earliest identity), else ('email', <id>). If another public.users
--    row holds that pair, the id is used as oauth_id instead.
-- 5. public.handle_new_user() (CREATE OR REPLACE): email = lower(btrim(auth email)), else
--    '<id>@unknown.local' (no user-metadata fallback). A public.users row with the same
--    email (case-insensitive) is removed only when it has no auth.users record. If
--    another row holds the new account's (provider, oauth_id) pair, the new row's
--    oauth_id is its own id. Sign-up never fails on either collision.
-- 6. public.user_id_for_auth_email(p_email): the public.users id whose auth.users email
--    matches (case-insensitive); NULL when more than one auth.users record matches.
--    With no auth.users match, a public.users row with that email and no auth.users
--    record (provisioned, not yet signed in) is returned. service_role only (EXECUTE
--    grant and an auth.role() check).
-- 7. public.admin_add_internal_user (CREATE OR REPLACE, same signature and result):
--    the target is the account whose auth.users email matches. None -> SQLSTATE P0002
--    (message unchanged); more than one -> a distinct message.
-- 8. public.sync_email_from_auth() (trigger on_auth_user_email_changed, AFTER UPDATE OF
--    email ON auth.users, WHEN the email changed): re-applies rule 1 to the person's
--    public.users row. Errors are caught and logged as a WARNING.
-- 9. Data: every auth-backed public.users row whose email differs from rule 1 is
--    rewritten through the trigger. The pre-check aborts if any target value is held by
--    another row.
--
-- CREATE OR REPLACE / ALTER only; no DROP, no BEGIN/COMMIT. Re-running is a no-op.
-- Rollback: supabase/tests/backlog-3998/rollback.sql (the previous email values are
-- not restored).

DO $pre$
DECLARE
  v_md5 text;
  r     record;
  v_n   int;
BEGIN
  -- Replaced functions: the bodies measured on production and keepr-test, or this file's.
  FOR r IN SELECT * FROM (VALUES
    ('public.handle_new_user()',                  '64c98e28c6916d1095fd70445e7812cf', 'd29adc102b649c9d53f754725feb66b3'),
    ('public.admin_add_internal_user(text,text)', '058aebe462132d39c60ab4cfdf9dbd55', 'd104c223d7e75ee270540b044203e9cd')
  ) AS t(sig, old_md5, new_md5) LOOP
    SELECT md5(p.prosrc) INTO v_md5 FROM pg_proc p WHERE p.oid = to_regprocedure(r.sig);
    IF v_md5 IS NULL OR v_md5 NOT IN (r.old_md5, r.new_md5) THEN
      RAISE EXCEPTION '3998 pre-check: % body md5 % is neither % nor %', r.sig, v_md5, r.old_md5, r.new_md5;
    END IF;
  END LOOP;

  -- New functions: absent, or already this file's body.
  FOR r IN SELECT * FROM (VALUES
    ('public.users_email_from_auth()',       'eb762a864ef17d09fa0e6351fbdd8468'),
    ('public.users_client_write_guard()',    '22a40e688af40dc838879df00f4e7133'),
    ('public.users_own_oauth_pair()',        'd74b56a52d1e2df4344cb584be5a0fab'),
    ('public.user_id_for_auth_email(text)',  'a6eb9a7dedf1edfe381f544a16cc6f9a'),
    ('public.sync_email_from_auth()',        '8dde26ff3b2c18b19c4e27ecb424025e')
  ) AS t(sig, expected) LOOP
    SELECT md5(p.prosrc) INTO v_md5 FROM pg_proc p WHERE p.oid = to_regprocedure(r.sig);
    IF v_md5 IS NOT NULL AND v_md5 <> r.expected THEN
      RAISE EXCEPTION '3998 pre-check: % exists with a different body (md5 %)', r.sig, v_md5;
    END IF;
  END LOOP;

  -- The update policy is the measured one (USING own id), with no WITH CHECK or this file's.
  SELECT count(*) INTO v_n FROM pg_policies
   WHERE schemaname = 'public' AND tablename = 'users' AND policyname = 'users_can_update_own_user'
     AND cmd = 'UPDATE' AND qual = '(( SELECT auth.uid() AS uid) = id)'
     AND (with_check IS NULL OR with_check = '(( SELECT auth.uid() AS uid) = id)');
  IF v_n <> 1 THEN
    RAISE EXCEPTION '3998 pre-check: users_can_update_own_user is not the expected policy';
  END IF;

  -- The columns authenticated may INSERT but not UPDATE are the measured 23, and the 17
  -- this file resets have the defaults users_client_write_guard writes.
  SELECT count(*) INTO v_n
    FROM pg_attribute at
   WHERE at.attrelid = 'public.users'::regclass AND at.attnum > 0 AND NOT at.attisdropped
     AND has_column_privilege('authenticated', 'public.users'::regclass, at.attnum, 'INSERT')
     AND NOT has_column_privilege('authenticated', 'public.users'::regclass, at.attnum, 'UPDATE')
     AND at.attname NOT IN ('status', 'suspended_at', 'suspension_reason', 'is_active',
       'subscription_tier', 'subscription_status', 'subscription_started_at', 'trial_ends_at',
       'provisioning_source', 'scim_external_id', 'is_managed', 'sso_only', 'last_sso_login_at',
       'last_sso_provider', 'jit_provisioned', 'jit_provisioned_at', 'idp_claims',
       'created_at', 'login_count', 'signup_source', 'do_not_sell_data', 'ccpa_opt_out_date',
       'current_onboarding_step');
  IF v_n <> 0 THEN
    RAISE EXCEPTION '3998 pre-check: % insert-only column(s) of public.users not classified by this file', v_n;
  END IF;

  SELECT count(*) INTO v_n
    FROM (VALUES
      ('status', '''active''::text'), ('suspended_at', NULL), ('suspension_reason', NULL),
      ('is_active', 'true'), ('subscription_tier', '''free''::text'),
      ('subscription_status', '''trial''::text'), ('subscription_started_at', NULL),
      ('trial_ends_at', '(now() + ''14 days''::interval)'),
      ('provisioning_source', '''manual''::text'), ('scim_external_id', NULL),
      ('is_managed', 'false'), ('sso_only', 'false'), ('last_sso_login_at', NULL),
      ('last_sso_provider', NULL), ('jit_provisioned', 'false'), ('jit_provisioned_at', NULL),
      ('idp_claims', NULL)
    ) AS e(col, dflt)
    LEFT JOIN pg_attribute at
      ON at.attrelid = 'public.users'::regclass AND at.attname = e.col AND at.attnum > 0 AND NOT at.attisdropped
    LEFT JOIN pg_attrdef d ON d.adrelid = at.attrelid AND d.adnum = at.attnum
   WHERE at.attnum IS NULL
      OR pg_get_expr(d.adbin, d.adrelid) IS DISTINCT FROM e.dflt
      OR NOT has_column_privilege('authenticated', 'public.users'::regclass, at.attnum, 'INSERT')
      OR has_column_privilege('authenticated', 'public.users'::regclass, at.attnum, 'UPDATE');
  IF v_n <> 0 THEN
    RAISE EXCEPTION '3998 pre-check: % reset column(s) missing, client-updatable, or with a different default', v_n;
  END IF;

  -- Data step: no auth-backed row's target email is held by another row.
  SELECT count(*) INTO v_n
    FROM public.users u
    JOIN auth.users a ON a.id = u.id
   WHERE NULLIF(lower(btrim(a.email)), '') IS NOT NULL
     AND u.email IS DISTINCT FROM lower(btrim(a.email))
     AND EXISTS (SELECT 1 FROM public.users o
                  WHERE o.id <> u.id AND o.email = lower(btrim(a.email)));
  IF v_n <> 0 THEN
    RAISE EXCEPTION '3998 pre-check: % row(s) cannot take their auth.users email (held by another row)', v_n;
  END IF;
END $pre$;

-- 1 ---------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.users_email_from_auth()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_found boolean;
  v_email text;
BEGIN
  SELECT true, lower(btrim(a.email)) INTO v_found, v_email
    FROM auth.users a WHERE a.id = NEW.id;
  IF v_found IS NOT TRUE THEN
    RETURN NEW;
  END IF;

  v_email := COALESCE(NULLIF(v_email, ''), NEW.id::text || '@unknown.local');

  IF EXISTS (SELECT 1 FROM public.users u
              WHERE u.email = v_email
                AND u.id <> NEW.id
                AND (TG_OP = 'INSERT' OR u.id <> OLD.id)) THEN
    RAISE WARNING 'users_email_from_auth: address held by another row; placeholder for %', NEW.id;
    v_email := NEW.id::text || '@unknown.local';
  END IF;

  NEW.email := v_email;
  RETURN NEW;
END;
$function$;

REVOKE ALL ON FUNCTION public.users_email_from_auth() FROM PUBLIC, anon, authenticated;

-- 4 ---------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.users_own_oauth_pair()
 RETURNS TABLE(provider text, provider_id text)
 LANGUAGE plpgsql
 STABLE
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_provider text;
  v_provider_id text;
BEGIN
  IF v_uid IS NULL THEN
    RETURN;
  END IF;

  SELECT i.provider, i.provider_id INTO v_provider, v_provider_id
    FROM auth.identities i
   WHERE i.user_id = v_uid
   ORDER BY i.created_at, i.id
   LIMIT 1;

  IF v_provider IS NULL OR v_provider_id IS NULL THEN
    v_provider := 'email';
    v_provider_id := v_uid::text;
  END IF;

  IF EXISTS (SELECT 1 FROM public.users u
              WHERE u.oauth_provider = v_provider AND u.oauth_id = v_provider_id
                AND u.id <> v_uid) THEN
    v_provider_id := v_uid::text;
  END IF;

  provider := v_provider;
  provider_id := v_provider_id;
  RETURN NEXT;
END;
$function$;

REVOKE ALL ON FUNCTION public.users_own_oauth_pair() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.users_own_oauth_pair() TO authenticated, service_role;

-- 3 ---------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.users_client_write_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_provider text;
  v_provider_id text;
BEGIN
  IF current_user NOT IN ('authenticated', 'anon') THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    NEW.oauth_provider := OLD.oauth_provider;
    NEW.oauth_id := OLD.oauth_id;
    RETURN NEW;
  END IF;

  SELECT p.provider, p.provider_id INTO v_provider, v_provider_id
    FROM public.users_own_oauth_pair() p;
  IF v_provider IS NOT NULL THEN
    NEW.oauth_provider := v_provider;
    NEW.oauth_id := v_provider_id;
  END IF;

  NEW.status := 'active';
  NEW.suspended_at := NULL;
  NEW.suspension_reason := NULL;
  NEW.is_active := true;
  NEW.subscription_tier := 'free';
  NEW.subscription_status := 'trial';
  NEW.subscription_started_at := NULL;
  NEW.trial_ends_at := now() + interval '14 days';
  NEW.provisioning_source := 'manual';
  NEW.scim_external_id := NULL;
  NEW.is_managed := false;
  NEW.sso_only := false;
  NEW.last_sso_login_at := NULL;
  NEW.last_sso_provider := NULL;
  NEW.jit_provisioned := false;
  NEW.jit_provisioned_at := NULL;
  NEW.idp_claims := NULL;
  RETURN NEW;
END;
$function$;

REVOKE ALL ON FUNCTION public.users_client_write_guard() FROM PUBLIC, anon, authenticated;

-- 5 ---------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_email TEXT;
  v_existing_id UUID;
  v_provider TEXT;
  v_oauth_id TEXT;
BEGIN
  v_email := COALESCE(NULLIF(lower(btrim(NEW.email)), ''), NEW.id::text || '@unknown.local');

  -- A row with this email and no auth.users record (left behind by a deleted account,
  -- or provisioned before first sign-in) is removed with its analytics events.
  FOR v_existing_id IN
    SELECT u.id FROM public.users u
     WHERE lower(btrim(u.email)) = v_email
       AND u.id <> NEW.id
       AND NOT EXISTS (SELECT 1 FROM auth.users a WHERE a.id = u.id)
  LOOP
    DELETE FROM public.analytics_events WHERE user_id = v_existing_id;
    DELETE FROM public.users WHERE id = v_existing_id;
  END LOOP;

  v_provider := COALESCE(NEW.raw_app_meta_data->>'provider', 'email');
  v_oauth_id := COALESCE(NEW.raw_user_meta_data->>'provider_id', NEW.raw_user_meta_data->>'sub', NEW.id::text);
  IF EXISTS (SELECT 1 FROM public.users u
              WHERE u.oauth_provider = v_provider AND u.oauth_id = v_oauth_id
                AND u.id <> NEW.id) THEN
    v_oauth_id := NEW.id::text;
  END IF;

  INSERT INTO public.users (
    id, email, display_name, avatar_url, oauth_provider, oauth_id,
    created_at, updated_at, is_active, status
  )
  VALUES (
    NEW.id,
    v_email,
    COALESCE(NEW.raw_user_meta_data->>'full_name', NEW.raw_user_meta_data->>'name', split_part(v_email, '@', 1)),
    NEW.raw_user_meta_data->>'avatar_url',
    v_provider,
    v_oauth_id,
    NOW(),
    NOW(),
    true,
    'active'
  )
  ON CONFLICT (id) DO UPDATE SET
    email = EXCLUDED.email,
    display_name = COALESCE(EXCLUDED.display_name, public.users.display_name),
    avatar_url = COALESCE(EXCLUDED.avatar_url, public.users.avatar_url),
    updated_at = NOW();

  RETURN NEW;
END;
$function$;

REVOKE ALL ON FUNCTION public.handle_new_user() FROM PUBLIC, anon, authenticated;

-- 6 ---------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.user_id_for_auth_email(p_email text)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_email text := lower(btrim(p_email));
  v_ids uuid[];
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'Not allowed' USING ERRCODE = '42501';
  END IF;
  IF v_email IS NULL OR v_email = '' THEN
    RETURN NULL;
  END IF;

  SELECT array_agg(a.id) INTO v_ids FROM auth.users a WHERE lower(btrim(a.email)) = v_email;
  IF cardinality(v_ids) > 1 THEN
    RETURN NULL;
  END IF;
  IF cardinality(v_ids) = 1 THEN
    RETURN (SELECT u.id FROM public.users u WHERE u.id = v_ids[1]);
  END IF;

  SELECT array_agg(u.id) INTO v_ids
    FROM public.users u
   WHERE lower(btrim(u.email)) = v_email
     AND NOT EXISTS (SELECT 1 FROM auth.users a WHERE a.id = u.id);
  IF cardinality(v_ids) = 1 THEN
    RETURN v_ids[1];
  END IF;
  RETURN NULL;
END;
$function$;

REVOKE ALL ON FUNCTION public.user_id_for_auth_email(text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.user_id_for_auth_email(text) TO service_role;

-- 7 ---------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.admin_add_internal_user(p_email text, p_role text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_target_user_id UUID;
  v_role_id UUID;
  v_existing RECORD;
  v_matches INT;
BEGIN
  IF NOT public.has_internal_role(auth.uid()) THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  SELECT id INTO v_role_id FROM public.admin_roles WHERE slug = REPLACE(p_role, '_', '-');
  IF v_role_id IS NULL THEN
    RAISE EXCEPTION 'Invalid role: %', p_role;
  END IF;

  SELECT count(*) INTO v_matches FROM auth.users a WHERE lower(btrim(a.email)) = lower(btrim(p_email));
  IF v_matches > 1 THEN
    RAISE EXCEPTION 'More than one account has email: %', p_email;
  END IF;

  SELECT u.id INTO v_target_user_id
    FROM auth.users a JOIN public.users u ON u.id = a.id
   WHERE lower(btrim(a.email)) = lower(btrim(p_email));
  IF v_target_user_id IS NULL THEN
    RAISE EXCEPTION 'No user found with email: %', p_email USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO v_existing FROM public.internal_roles WHERE user_id = v_target_user_id;
  IF FOUND THEN
    RAISE EXCEPTION 'User already has an internal role';
  END IF;

  INSERT INTO public.internal_roles (user_id, role_id, created_by)
  VALUES (v_target_user_id, v_role_id, auth.uid());

  PERFORM public.log_admin_action(
    'internal_user.add',
    'internal_role',
    v_target_user_id::TEXT,
    jsonb_build_object(
      'after', jsonb_build_object(
        'email', p_email,
        'role', p_role,
        'user_id', v_target_user_id
      )
    )
  );

  RETURN jsonb_build_object('success', true, 'user_id', v_target_user_id, 'role', p_role);
END;
$function$;

REVOKE ALL ON FUNCTION public.admin_add_internal_user(text, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.admin_add_internal_user(text, text) TO authenticated, service_role;

-- 8 ---------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.sync_email_from_auth()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  BEGIN
    UPDATE public.users SET email = NEW.email WHERE id = NEW.id;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'sync_email_from_auth: % %', SQLSTATE, SQLERRM;
  END;
  RETURN NULL;
END;
$function$;

REVOKE ALL ON FUNCTION public.sync_email_from_auth() FROM PUBLIC, anon, authenticated;

-- Triggers and policy ----------------------------------------------------------------
DO $trg$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_trigger
                  WHERE tgrelid = 'public.users'::regclass AND tgname = 'users_email_from_auth') THEN
    CREATE TRIGGER users_email_from_auth
      BEFORE INSERT OR UPDATE OF email, id ON public.users
      FOR EACH ROW EXECUTE FUNCTION public.users_email_from_auth();
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_trigger
                  WHERE tgrelid = 'public.users'::regclass AND tgname = 'users_client_write_guard') THEN
    CREATE TRIGGER users_client_write_guard
      BEFORE INSERT OR UPDATE OF oauth_provider, oauth_id ON public.users
      FOR EACH ROW EXECUTE FUNCTION public.users_client_write_guard();
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_trigger
                  WHERE tgrelid = 'auth.users'::regclass AND tgname = 'on_auth_user_email_changed') THEN
    CREATE TRIGGER on_auth_user_email_changed
      AFTER UPDATE OF email ON auth.users
      FOR EACH ROW WHEN (OLD.email IS DISTINCT FROM NEW.email)
      EXECUTE FUNCTION public.sync_email_from_auth();
  END IF;
END $trg$;

ALTER POLICY users_can_update_own_user ON public.users
  WITH CHECK ((SELECT auth.uid()) = id);

-- 9 ---------------------------------------------------------------------------------
UPDATE public.users u
   SET email = u.email
  FROM auth.users a
 WHERE a.id = u.id
   AND u.email IS DISTINCT FROM COALESCE(NULLIF(lower(btrim(a.email)), ''), u.id::text || '@unknown.local');

DO $c14$
DECLARE rep text;
BEGIN
  SELECT string_agg(p.proname || '=' || md5(p.prosrc), ' ' ORDER BY p.proname) INTO rep FROM pg_proc p
   WHERE p.pronamespace = 'public'::regnamespace
     AND p.proname IN ('users_email_from_auth', 'users_client_write_guard', 'users_own_oauth_pair',
                       'user_id_for_auth_email', 'admin_add_internal_user', 'sync_email_from_auth', 'handle_new_user');
  RAISE EXCEPTION 'C14 REPORT %', rep;
END $c14$;
